CREATE TABLE spaces (space_id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL, learning_enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE devices (device_id TEXT PRIMARY KEY, space_id TEXT NOT NULL, provider TEXT NOT NULL, provider_device_id TEXT NOT NULL, device_type TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(space_id) REFERENCES spaces(space_id));
CREATE TABLE zones (zone_id TEXT PRIMARY KEY, space_id TEXT NOT NULL, name TEXT NOT NULL, zone_type TEXT NOT NULL, sensitivity REAL NOT NULL, FOREIGN KEY(space_id) REFERENCES spaces(space_id));
CREATE TABLE events (event_id TEXT PRIMARY KEY, source TEXT NOT NULL, source_event_id TEXT NOT NULL, space_id TEXT NOT NULL, device_id TEXT NOT NULL, zone_id TEXT NOT NULL, event_type TEXT NOT NULL, occurred_at TEXT NOT NULL, received_at TEXT NOT NULL, payload_json TEXT NOT NULL, UNIQUE(source, source_event_id));
CREATE INDEX idx_events_space_time ON events(space_id, occurred_at);
CREATE TABLE observations (observation_id TEXT PRIMARY KEY, space_id TEXT NOT NULL, type TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, zone_id TEXT NOT NULL, confidence REAL NOT NULL, evidence_event_ids_json TEXT NOT NULL, features_json TEXT NOT NULL);
CREATE TABLE routine_profiles (space_id TEXT NOT NULL, zone_id TEXT NOT NULL, profile_version INTEGER NOT NULL, profile_json TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(space_id, zone_id, profile_version));
CREATE TABLE anomalies (anomaly_id TEXT PRIMARY KEY, space_id TEXT NOT NULL, observation_id TEXT NOT NULL, model_json TEXT NOT NULL, score REAL NOT NULL, severity TEXT NOT NULL, features_json TEXT NOT NULL, detected_at TEXT NOT NULL);
CREATE TABLE incidents (incident_id TEXT PRIMARY KEY, space_id TEXT NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, started_at TEXT NOT NULL, updated_at TEXT NOT NULL, risk_json TEXT NOT NULL, evidence_json TEXT NOT NULL, resolution TEXT);
CREATE TABLE actions (action_id TEXT PRIMARY KEY, incident_id TEXT NOT NULL, type TEXT NOT NULL, requested_by TEXT NOT NULL, policy_json TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, executed_at TEXT);
CREATE TABLE privacy_preferences (space_id TEXT PRIMARY KEY, preferences_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audit_logs (audit_id INTEGER PRIMARY KEY AUTOINCREMENT, occurred_at TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT, details_json TEXT NOT NULL);
